import gzip
import io

html = """<!doctype html><html lang="uk"><head><meta charset="UTF-8"><link rel="icon" href="data:image"><meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no"><title>HTRAM — Wi-Fi</title><style>:root{--bg:#090d16;--card:#131b2e;--border:#1e293b;--text:#f1f5f9;--text-muted:#94a3b8;--primary:#38bdf8;--radius:10px}*{box-sizing:border-box;margin:0;padding:0}body{background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;padding:16px;line-height:1.5;text-align:center}main{max-width:420px;margin:0 auto;text-align:left}h1{font-size:1.5rem;font-weight:700;color:#fff;margin-bottom:4px}h3{font-size:1rem;font-weight:600;color:var(--text)}.subtitle{color:var(--text-muted);font-size:0.85rem;margin-bottom:16px}.card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:14px;margin-bottom:16px}.card-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.btn-ref{background:rgba(56,189,248,0.12);color:var(--primary);border:1px solid rgba(56,189,248,0.25);border-radius:6px;padding:4px 9px;font-size:0.8rem;cursor:pointer;font-weight:500}.btn-ref:hover{background:rgba(56,189,248,0.25)}.networks-container{max-height:190px;overflow-y:auto;margin-bottom:12px;border:1px solid var(--border);border-radius:8px;background:#0b1120}.network{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-bottom:1px solid var(--border);cursor:pointer;transition:background 0.15s}.network:hover{background:rgba(56,189,248,0.08)}.network:last-child{border-bottom:none}.network-left{display:flex;align-items:center;gap:9px;color:var(--text);font-size:0.92rem;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}input{width:100%;background:#0b1120;border:1px solid var(--border);border-radius:8px;color:var(--text);padding:10px 12px;font-size:0.95rem;margin-bottom:10px;outline:none;box-sizing:border-box}input:focus{border-color:var(--primary)}button[type="submit"]{border:0;border-radius:8px;background-color:var(--primary);color:#090d16;font-weight:600;font-size:1rem;width:100%;padding:12px;cursor:pointer}.info-card{background:rgba(56,189,248,0.05);border:1px solid rgba(56,189,248,0.2);border-radius:var(--radius);padding:14px;font-size:0.88rem}.info-card h4{color:var(--primary);font-size:0.92rem;margin-bottom:8px}.info-card ol{margin-left:20px;margin-bottom:10px}.info-card li{margin-bottom:6px}.hint-box{border-top:1px solid var(--border);padding-top:8px;color:var(--text-muted);font-size:0.82rem}.hint-box b{color:var(--text)}</style><script type="module">function o(e){let t=Math.max(Math.min(2*(e+100),100),0)/100;return`<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24"><path d="M12 19.25L.7 4.25c7-5 14-5 22.5 0z" fill="none" stroke="#94a3b8"/><path d="M12 19.25L.7 4.25c7-5 14-5 22.5 0z" fill="#38bdf8" transform="scale(${t} ${t})" transform-origin="12 18"/></svg>`}function r(e){return e?`<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="#94a3b8"><path d="M12 17a2 2 0 0 0 2-2 2 2 0 0 0-2-2 2 2 0 0 0-2 2 2 2 0 0 0 2 2m6-9a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V10a2 2 0 0 1 2-2h1V6a5 5 0 0 1 5-5 5 5 0 0 1 5 5v2h1m-6-5a3 3 0 0 0-3 3v2h6V6a3 3 0 0 0-3-3z"/></svg>`:""}let pt=null;function loadNets(rescan=false,retry=0){if(pt)clearTimeout(pt);let c=document.getElementById("net");if(retry===0){c.innerHTML='<div style="padding:14px;color:#94a3b8;text-align:center">⏳ Пошук доступних мереж...</div>';}fetch("/config.json"+(rescan?"?rescan=1":"")).then(e=>e.json()).then(t=>{if(t.name&&t.mac)document.getElementById("mac").innerText=t.name+" ("+t.mac+")";let i=document.getElementById("ssid"),l=document.getElementById("psk");let m=new Map();(t.aps||[]).forEach(s=>{if(s&&s.ssid&&s.ssid.trim().length>0){if(!m.has(s.ssid)||m.get(s.ssid).rssi<s.rssi){m.set(s.ssid,s)}}});let list=Array.from(m.values()).sort((a,b)=>b.rssi-a.rssi);if(list.length>0){c.innerHTML="";list.forEach(s=>{let n=document.createElement("div");n.className="network";n.innerHTML=`<div class="network-left">${o(s.rssi)}<span>${s.ssid}</span></div>${r(s.lock)}`;n.onclick=()=>{i.value=s.ssid;l.focus()};c.appendChild(n)})}else if(retry<4){pt=setTimeout(()=>loadNets(false,retry+1),1500)}else{c.innerHTML='<div style="padding:12px;color:#94a3b8;text-align:center">Мереж не знайдено (<a href="#" id="link-ref" style="color:var(--primary)">оновити</a> або ввести вручну)</div>';let lr=document.getElementById("link-ref");if(lr)lr.onclick=(ev)=>{ev.preventDefault();loadNets(true,0)}}}).catch(()=>{if(retry<2){pt=setTimeout(()=>loadNets(false,retry+1),1500)}else{c.innerHTML='<div style="padding:12px;color:#94a3b8;text-align:center">Введіть параметри мережі вручну</div>'}})}window.addEventListener("DOMContentLoaded",()=>{let b=document.getElementById("btn-ref");if(b)b.onclick=()=>loadNets(true,0);loadNets(false,0)});window.sub=function(e){e.preventDefault();let i=document.getElementById("ssid").value.trim(),p=document.getElementById("psk").value;if(!i)return false;document.getElementById("form-card").style.display="none";document.getElementById("info-card").style.display="none";document.getElementById("succ-card").style.display="block";let b=new URLSearchParams();b.append("ssid",i);b.append("psk",p);fetch("/wifisave",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:b.toString()}).catch(()=>{});return false;};</script></head><body><main><h1>HTRAM</h1><div class="subtitle" id="mac">Підключення до Wi-Fi</div><div class="card" id="form-card"><div class="card-header"><h3>Доступні мережі Wi-Fi</h3><button type="button" id="btn-ref" class="btn-ref">↻ Оновити</button></div><div id="net" class="networks-container"></div><form action="/wifisave" method="POST" onsubmit="return window.sub(event)"><input id="ssid" name="ssid" maxlength="32" placeholder="Назва мережі (SSID)" required autocomplete="off"><input id="psk" name="psk" maxlength="64" type="password" placeholder="Пароль мережі" autocomplete="current-password"><button type="submit" id="btn-sub">Зберегти та підключитися</button></form></div><div class="card" id="succ-card" style="display:none;border-color:#22c55e"><h2 style="color:#22c55e;margin-bottom:12px;font-size:1.3rem">✓ Пароль збережено!</h2><p style="margin-bottom:12px">Годинник зараз підключається до вашого Wi-Fi...</p><ol style="padding-left:20px;margin-bottom:14px"><li style="margin-bottom:8px">Зачекайте кілька секунд, поки телефон повернеться у ваш домашній Wi-Fi.</li><li style="margin-bottom:8px">Подивіться на екран годинника — там з'явиться <b>QR-код для переходу в налаштування</b>.</li><li style="margin-bottom:8px">Відскануйте QR-код (або відкрийте <b>http://htram.local</b>), щоб налаштувати місто для тривог і погоди.</li></ol><div class="hint-box">💡 <b>Підказка:</b> QR-код налаштувань завжди доступний за <b>4 швидкими кліками</b> на кнопку годинника.</div></div><div class="info-card" id="info-card"><h4>Що відбудеться після збереження:</h4><ol><li>Годинник підключиться до вашого домашнього Wi-Fi.</li><li>Телефон автоматично повернеться до вашої домашньої мережі.</li><li>Подивіться на екран годинника та відскануйте <b>QR-код налаштувань</b> (або відкрийте <b>http://htram.local</b>).</li></ol><div class="hint-box">💡 <b>Підказка:</b> QR-код для переходу в налаштування завжди доступний за <b>4 швидкими кліками</b> на кнопку годинника.</div></div></main></body></html>"""

compressed_gz = gzip.compress(html.encode("utf-8"), 9)
print(f"Compressed size: {len(compressed_gz)} bytes")

out = io.StringIO()
out.write("#pragma once\n")
out.write('#include "esphome/core/hal.h"\n\n')
out.write("namespace esphome::captive_portal {\n\n")
out.write("#ifdef USE_CAPTIVE_PORTAL_GZIP\n")
out.write(f"constexpr uint8_t INDEX_GZ[{len(compressed_gz)}] PROGMEM = {{\n")
for i, byte in enumerate(compressed_gz):
    if i % 16 == 0:
        out.write("    ")
    out.write(f"0x{byte:02x}, ")
    if i % 16 == 15 or i == len(compressed_gz) - 1:
        out.write("\n")
out.write("};\n#endif\n\n")
out.write("constexpr uint8_t INDEX_BR[] PROGMEM = { 0x00 };\n\n")
out.write("}  // namespace esphome::captive_portal\n")

with open("esphome/custom_components/captive_portal/captive_index.h", "w", encoding="utf-8") as f:
    f.write(out.getvalue())

print("Written captive_index.h successfully!")
